def nyse_sessions(start, end):
    if start < pd.Timestamp("2008-01-01") or end > pd.Timestamp("2025-12-31"):
        raise ValueError("The NYSE calendar covers 2008–2025 only")
    # Hurricane Sandy and the national days of mourning for Bush and Carter.
    closures = pd.to_datetime(["2012-10-29", "2012-10-30", "2018-12-05", "2025-01-09"])
    holidays = NyseHolidays().holidays(start, end).union(closures)
    return pd.bdate_range(start, end).difference(holidays)


@dataclass(frozen=True)
class Model:
    lookback_sessions: int
    risk_aversion: float
    delta: float

    def __post_init__(self):
        if type(self.lookback_sessions) is not int or self.lookback_sessions < 2:
            raise ValueError("lookback_sessions must be an integer of at least two")
        if not np.isfinite(self.risk_aversion) or self.risk_aversion <= 0:
            raise ValueError("risk_aversion must be finite and positive")
        if not np.isfinite(self.delta) or self.delta < 0:
            raise ValueError("delta must be finite and nonnegative")


def check_prices(prices, tickers, sessions):
    if prices.empty or prices.index.has_duplicates:
        raise ValueError("Expected a nonempty Yahoo Finance panel with unique sessions")
    if not prices.index.equals(sessions):
        missing = sessions.difference(prices.index).strftime("%Y-%m-%d").tolist()
        unexpected = prices.index.difference(sessions).strftime("%Y-%m-%d").tolist()
        raise ValueError(f"NYSE calendar mismatch (missing: {missing[:5]}, unexpected: {unexpected[:5]})")
    problems = (~np.isfinite(prices)) | (prices <= 0)
    if problems.any().any():
        rows, cols = np.where(problems.to_numpy())
        examples = ", ".join(f"{prices.index[row]:%Y-%m-%d} {tickers[col]}"
                             for row, col in zip(rows[:5], cols[:5], strict=True))
        raise ValueError(f"Missing or invalid adjusted closes: {examples}")



def load_config(config_path="config.yaml"):
    with open(config_path, "rb") as file:
        raw = file.read()
    return yaml.safe_load(raw), raw


def load_prices(settings, tickers, sessions, config_path="config.yaml"):
    data = settings.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = gzip.decompress(bytes(blob))
    digest = sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the market snapshot in {Path(config_path).name}: {digest}."
        )
    header, sep, body = snapshot.partition(b"\n")
    if not sep:
        raise ValueError("Missing cache timestamp")
    fetched_at = header.decode("utf-8").strip()
    price_timestamp = datetime.fromisoformat(fetched_at)
    input_digest = sha256(body).hexdigest()
    with BytesIO(snapshot) as source:
        source.readline()
        prices = pd.read_csv(source, index_col="Date", parse_dates=["Date"])
    prices = prices.reindex(columns=tickers).sort_index()
    check_prices(prices, tickers, sessions)
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: yfinance auto_adjust snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); the script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    return prices, price_timestamp


def fit_weights(window, model):
    mean = window.mean(axis=0)
    mean = mean - mean.mean()  # Subtract a constant from the simplex objective.
    variance = model.risk_aversion * LedoitWolf().fit(window).covariance_
    penalty = np.sqrt(model.delta)
    scale = max(np.max(np.abs(mean)), np.max(np.abs(variance)), penalty, 1e-12)
    mean, variance, penalty = mean / scale, variance / scale, penalty / scale

    def loss(weights):
        variance_gradient = variance @ weights
        norm = np.linalg.norm(weights)
        value = weights @ (variance_gradient - mean) + penalty * norm
        gradient = 2 * variance_gradient - mean + penalty * weights / norm
        return value, gradient

    n_assets = len(mean)
    initial = np.full(n_assets, 1 / n_assets)
    ones = np.ones(n_assets)
    result = minimize(
        loss, initial, jac=True, method="SLSQP", bounds=[(0, 1)] * n_assets,
        constraints={"type": "eq", "fun": lambda w: w.sum() - 1, "jac": lambda w: ones},
        options={"ftol": 1e-12, "maxiter": 200},
    )
    weights = result.x
    if not np.isfinite(weights).all() or weights.min() < -1e-8 or abs(weights.sum() - 1) > 1e-8:
        raise RuntimeError(f"Infeasible optimisation result: {result.message}")
    weights = np.maximum(weights, 0)
    weights /= weights.sum()
    # The linearisation gives an upper bound on the objective gap over the simplex.
    _, gradient = loss(weights)
    if weights @ gradient - gradient.min() > 2e-5:
        raise RuntimeError(f"Optimisation did not reach the gap tolerance: {result.message}")
    return weights


def rebalance_indices(index, start, lag):
    month = index.to_period("M")
    signal_indices = np.flatnonzero(month[:-1] != month[1:])
    # An evaluation cutoff can fall between a sale and its following purchase.
    return [(i, i + lag) for i in signal_indices if start <= i + lag < len(index)]


def build_targets(returns, schedule, model):
    targets = {}
    values = returns.to_numpy()
    for signal_index, sale_index in schedule:
        start = signal_index + 1 - model.lookback_sessions
        if start < 0:
            raise ValueError(f"Insufficient warm-up history for {returns.index[signal_index]:%Y-%m-%d}")
        try:
            weights = fit_weights(values[start:signal_index + 1], model)
        except RuntimeError as error:
            raise RuntimeError(f"{returns.index[signal_index]:%Y-%m-%d}: {error}") from error
        targets[returns.index[sale_index]] = weights
    return targets


def size_changes(positions, prior_close, prior_value, target, cash_buffer):
    """Determine the signed quantities using information at the prior close."""
    target_units = prior_value * (1 - cash_buffer) * target / prior_close
    changes = target_units - positions
    changes[np.abs(changes) * prior_close <= TRADE_TOLERANCE * prior_value] = 0
    return changes


def size_purchases(proposed_buys, prior_close, prior_value, cash, fee_rate, cash_buffer):
    """Use the completed sale session to budget quantities for the next close."""
    estimated_cost = (proposed_buys @ prior_close) * (1 + fee_rate)
    if estimated_cost == 0:
        return proposed_buys
    available_cash = max(0.0, cash - cash_buffer * prior_value)
    buys = proposed_buys * min(1.0, available_cash / estimated_cost)
    buys[buys * prior_close <= TRADE_TOLERANCE * prior_value] = 0
    return buys


def settle_fill(date, cash, fixed_changes, close, fee_rate):
    """Settle the preset quantities and reject a fill that would overdraw cash."""
    fill_values = fixed_changes * close
    gross_traded = np.abs(fill_values).sum()
    fees = gross_traded * fee_rate
    remaining_cash = cash - fill_values.sum() - fees
    if not np.isfinite(remaining_cash) or remaining_cash < 0:
        raise RuntimeError(
            f"{date:%Y-%m-%d}: preset quantities would leave negative or non-finite cash "
            f"({remaining_cash:.8g}) after costs"
        )
    return remaining_cash, gross_traded, fees


def simulate(prices, evaluation_index, targets, fee_rate, cash_buffer):
    positions = np.zeros(prices.shape[1])
    cash = 1.0
    daily_results = []
    pending_purchase = None
    prior_closes = prices.shift(1).loc[evaluation_index].to_numpy()
    closes = prices.loc[evaluation_index].to_numpy()
    for row, (date, prior_close) in enumerate(zip(evaluation_index, prior_closes, strict=True)):
        prior_value = cash + positions @ prior_close
        target = targets.get(date)
        fixed_changes = None
        completed_target = None
        proposed_buys = None
        if pending_purchase is not None:
            if target is not None:
                raise ValueError(f"{date:%Y-%m-%d}: overlapping rebalance sessions")
            fixed_changes, completed_target = pending_purchase
            pending_purchase = None
        elif target is not None:
            proposed_changes = size_changes(positions, prior_close, prior_value, target, cash_buffer)
            fixed_changes = np.minimum(proposed_changes, 0)
            fixed_changes.setflags(write=False)
            proposed_buys = np.maximum(proposed_changes, 0)

        # Quantity selection for this fill ends before reading this session's close.
        close = closes[row]
        fees = 0.0
        turnover = 0.0
        trades = 0
        if fixed_changes is not None:
            prefill_value = cash + positions @ close
            cash, gross_traded, fees = settle_fill(date, cash, fixed_changes, close, fee_rate)
            positions += fixed_changes
            turnover = gross_traded / prefill_value
            trades = int(np.count_nonzero(fixed_changes))
        close_value = cash + positions @ close
        if proposed_buys is not None:
            # This close and the net sale proceeds precede the next session's purchase fill.
            fixed_buys = size_purchases(proposed_buys, close, close_value, cash, fee_rate, cash_buffer)
            fixed_buys.setflags(write=False)
            pending_purchase = (fixed_buys, target)
        weight_gap = np.nan
        if completed_target is not None:
            target_exposure = completed_target * (1 - cash_buffer)
            weight_gap = np.max(np.abs(positions * close / close_value - target_exposure))
        daily_results.append((close_value / prior_value - 1, turnover, trades,
                              fees, cash / close_value, weight_gap))
    return pd.DataFrame(
        daily_results, index=evaluation_index,
        columns=["return", "turnover", "trades", "fees", "cash_weight", "weight_gap"],
    )


def execution_summary(daily_results):
    max_weight_gap = daily_results["weight_gap"].max()
    return {
        "fees_per_unit_initial_capital": float(daily_results["fees"].sum()),
        "min_cash_weight": float(daily_results["cash_weight"].min()),
        "max_weight_gap": float(max_weight_gap) if pd.notna(max_weight_gap) else None,
    }


def metrics(daily_results, cash_returns):
    returns = daily_results["return"].to_numpy()
    excess = returns - cash_returns.loc[daily_results.index].to_numpy()
    growth = np.cumprod(np.r_[1.0, 1 + returns])
    volatility = returns.std(ddof=1) if np.ptp(returns) > 0 else 0.0
    excess_volatility = excess.std(ddof=1) if np.ptp(excess) > 0 else 0.0
    annualizer = np.sqrt(SESSIONS_PER_YEAR)
    return {
        "cagr": float(growth[-1] ** (SESSIONS_PER_YEAR / len(returns)) - 1),
        "ann_vol": float(volatility * annualizer),
        "sharpe": float(returns.mean() * annualizer / volatility) if volatility > 0 else None,
        "sharpe_excess": float(excess.mean() * annualizer / excess_volatility) if excess_volatility > 0 else None,
        "max_drawdown": float((growth / np.maximum.accumulate(growth) - 1).min()),
        "total_return": float(growth[-1] - 1),
        "turnover": float(daily_results["turnover"].mean() * SESSIONS_PER_YEAR),
        "n_trades": int(daily_results["trades"].sum()),
    }


def median_breadth(targets):
    return float(np.median([1 / (weights @ weights) for weights in targets.values()]))


def main():
    config, _ = load_config(str(ROOT / "config.yaml"))
    universe = config["universe"]
    cash_ticker = config["risk_free_ticker"]
    if len(universe) != len(SECTOR_ETFS) or set(universe) != SECTOR_ETFS or cash_ticker != "BIL":
        raise ValueError("Use the nine original Select Sector SPDR ETFs and BIL as the cash proxy")
    dates = config["dates"]
    start, evaluation_start, split, end = (
        pd.Timestamp(dates[key]) for key in ("price_start", "evaluation_start", "is_end", "end")
    )
    if not start < evaluation_start <= split < end:
        raise ValueError("Expected price_start < evaluation_start <= is_end < end")
    lag = config["execution"]["lag_sessions"]
    if type(lag) is not int or lag < 1:
        raise ValueError("lag_sessions must be a positive integer")
    costs = [float(config["execution"][key]) for key in ("cost_bps", "slippage_bps")]
    fee_rate = sum(costs) / 10_000
    if not all(cost >= 0 for cost in costs) or not fee_rate < 1:
        raise ValueError("Cost and slippage must be nonnegative and sum to fewer than 10,000 bps")
    cash_buffer = float(config["execution"]["cash_buffer"])
    if not 0 < cash_buffer < 1:
        raise ValueError("cash_buffer must be strictly between zero and one")
    official = Model(**config["model"])
    variants = [replace(official, **overrides) for overrides in config["robustness"]]
    if len(set([official, *variants])) != 1 + len(variants):
        raise ValueError("The robustness list must contain distinct alternatives to the official model")

    sessions = nyse_sessions(start, end)
    prices, fetched_at = load_prices(config, [*universe, cash_ticker], sessions, str(ROOT / "config.yaml"))
    asset_prices = prices[universe]
    daily_returns = prices.pct_change(fill_method=None).iloc[1:]
    cash_returns = daily_returns[cash_ticker]
    asset_returns = daily_returns[universe]
    evaluation = asset_returns.loc[evaluation_start:]
    is_history = asset_returns.loc[:split]
    is_evaluation = evaluation.loc[:split]
    return_sessions = sessions[1:]
    first_evaluation = return_sessions.searchsorted(evaluation_start)
    schedule = rebalance_indices(return_sessions, first_evaluation, lag)
    is_schedule = rebalance_indices(return_sessions[return_sessions <= split], first_evaluation, lag)
    if len(is_evaluation) < 2 or len(evaluation) - len(is_evaluation) < 2 or not is_schedule:
        raise ValueError("Need at least one executable IS signal and two return sessions per period")

    print(f"DATA_FETCHED_AT: {fetched_at.isoformat()}")
    print("PRICE_ADJUSTMENT: yfinance auto_adjust total-return adjusted close")
    print("ROBUSTNESS: in-sample only, one parameter changed at a time")
    for overrides, model in zip(config["robustness"], variants, strict=True):
        targets = build_targets(is_history, is_schedule, model)
        daily_results = simulate(asset_prices.loc[:split], is_evaluation.index, targets, fee_rate, cash_buffer)
        summary = metrics(daily_results, cash_returns)
        summary["median_effective_breadth"] = median_breadth(targets)
        print(f"ROBUSTNESS_IS {json.dumps(overrides)}: {json.dumps(summary, allow_nan=False)}")
    targets = build_targets(asset_returns, schedule, official)
    daily_results = simulate(asset_prices, evaluation.index, targets, fee_rate, cash_buffer)
    equal_weights = np.full(len(universe), 1 / len(universe))
    comparison = simulate(asset_prices, evaluation.index, dict.fromkeys(targets, equal_weights), fee_rate, cash_buffer)
    is_targets = {return_sessions[i]: targets[return_sessions[i]] for _, i in is_schedule}
    print(f"PARAM_COMBOS_TRIED: {1 + len(variants)}")
    print("BENCHMARK: same sector ETFs, equal-weight monthly with the same execution and costs")
    print(f"OFFICIAL_IS_MEDIAN_EFFECTIVE_BREADTH: {median_breadth(is_targets):.6f}")
    print(f"EXECUTION_STRATEGY: {json.dumps(execution_summary(daily_results), allow_nan=False)}")
    print(f"EXECUTION_BENCHMARK: {json.dumps(execution_summary(comparison), allow_nan=False)}")

    results = {
        "strategy": config["strategy"],
        "data_range": {
            "start": evaluation.index[0].date().isoformat(),
            "end": evaluation.index[-1].date().isoformat(),
        },
    }
    in_sample = evaluation.index <= split
    for period, selected in (("is", in_sample), ("oos", ~in_sample), ("full", slice(None))):
        results[period] = metrics(daily_results.loc[selected], cash_returns)
        benchmark = metrics(comparison.loc[selected], cash_returns)
        print(f"{period.upper()}: {json.dumps(results[period], allow_nan=False)}")
        print(f"BENCHMARK_{period.upper()}: {json.dumps(benchmark, allow_nan=False)}")
    results["benchmark"] = benchmark
    print("RESULTS_JSON: " + json.dumps(results, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(9 * 60)
    try:
        main()
    finally:
        signal.alarm(0)
